/* HEXA BATTLEGROUNDS setup — PART 60 OF 84. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-bomb-0', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Yellow, White, Blue, Red, Red.\nSerial number: SR59Q8.  LED: GREEN.","game":{"type":"bomb","wires":["black","yellow","white","blue","red","red"],"serial":"SR59Q8","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["6"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,yellow,white,blue,red,red · SR59Q8 · green → more than one red → last red → wire 6', null, 25, 'published'), ('mission-bomb-1', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Blue, White, Red, Green, Blue.\nSerial number: HX60Q5.  LED: RED.","game":{"type":"bomb","wires":["blue","white","red","green","blue"],"serial":"HX60Q5","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'blue,white,red,green,blue · HX60Q5 · red → serial ends odd and there is blue → first blue → wire 1', null, 25, 'published'), ('mission-bomb-2', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Blue, Yellow, White, Blue.\nSerial number: SR39Z0.  LED: RED.","game":{"type":"bomb","wires":["blue","yellow","white","blue"],"serial":"SR39Z0","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire 